import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/bivariate/bivariate_2021_gas_ghg.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create a dictionary to store the adjacency relationships
adjacency_dict = {}
for index, row in adjacency_df.iterrows():
    if row['borough'] not in adjacency_dict:
        adjacency_dict[row['borough']] = []
    adjacency_dict[row['borough']].append(row['neighbor'])

# Create a list to store the boroughs with high Gas values
high_gas_boroughs = []
for index, row in df.iterrows():
    if row['Gas_value'] > df['Gas_value'].mean():
        high_gas_boroughs.append(row['borough'])

# Create a list to store the boroughs with high GHG values
high_ghg_boroughs = []
for index, row in df.iterrows():
    if row['GHG_value'] > df['GHG_value'].mean():
        high_ghg_boroughs.append(row['borough'])

# Create a list to store the boroughs with low GHG values
low_ghg_boroughs = []
for index, row in df.iterrows():
    if row['GHG_value'] < df['GHG_value'].mean():
        low_ghg_boroughs.append(row['borough'])

# Calculate the number of high Gas boroughs that are neighbors of high GHG boroughs
num_high_gas_neighbors_high_ghg = 0
for borough in high_gas_boroughs:
    if borough in adjacency_dict and any(neighbor in high_ghg_boroughs for neighbor in adjacency_dict[borough]):
        num_high_gas_neighbors_high_ghg += 1

# Calculate the number of high Gas boroughs that are neighbors of low GHG boroughs
num_high_gas_neighbors_low_ghg = 0
for borough in high_gas_boroughs:
    if borough in adjacency_dict and any(neighbor in low_ghg_boroughs for neighbor in adjacency_dict[borough]):
        num_high_gas_neighbors_low_ghg += 1

# Calculate the total number of high Gas boroughs
total_high_gas_boroughs = len(high_gas_boroughs)

# Calculate the proportion of high Gas boroughs that are neighbors of high GHG boroughs
proportion_high_gas_neighbors_high_ghg = num_high_gas_neighbors_high_ghg / total_high_gas_boroughs

# Calculate the proportion of high Gas boroughs that are neighbors of low GHG boroughs
proportion_high_gas_neighbors_low_ghg = num_high_gas_neighbors_low_ghg / total_high_gas_boroughs

# Perform a permutation test to determine the significance of the relationship
p_value = 0
for _ in range(500):
    # Shuffle the adjacency relationships
    shuffled_adjacency_dict = {}
    for borough in adjacency_dict:
        shuffled_adjacency_dict[borough] = np.random.choice(adjacency_dict[borough], size=len(adjacency_dict[borough]))

    # Calculate the number of high Gas boroughs that are neighbors of high GHG boroughs in the shuffled adjacency relationships
    num_high_gas_neighbors_high_ghg_shuffled = 0
    for borough in high_gas_boroughs:
        if borough in shuffled_adjacency_dict and any(neighbor in high_ghg_boroughs for neighbor in shuffled_adjacency_dict[borough]):
            num_high_gas_neighbors_high_ghg_shuffled += 1

    # Calculate the proportion of high Gas boroughs that are neighbors of high GHG boroughs in the shuffled adjacency relationships
    proportion_high_gas_neighbors_high_ghg_shuffled = num_high_gas_neighbors_high_ghg_shuffled / total_high_gas_boroughs

    # Update the p-value if the proportion in the shuffled adjacency relationships is greater than the proportion in the original adjacency relationships
    if proportion_high_gas_neighbors_high_ghg_shuffled >= proportion_high_gas_neighbors_high_ghg:
        p_value += 1

# Print the final answer
print(f"FINAL ANSWER: POSITIVE (test statistic (a real number) = {proportion_high_gas_neighbors_high_ghg}, p = {p_value / 500})")
